"""Offline review: actual inspected PNGs, local font, no external resources or JS."""
from pathlib import Path
import base64,hashlib,html,json
root=Path(__file__).resolve().parents[4];matrix=root/'docs/ai/ui-rebuild/phase-3/matrix'
priority=['revision','contrast-revision','fx-revision','drag-revision','dialog-layout-revision','intake-revision','fixture-revision','user-create-final','earth-final','earth-marker-revision','state-revision','rail-final','state-final'];images={}
for folder in sorted(matrix.iterdir(),key=lambda p:(p.name in priority,priority.index(p.name) if p.name in priority else 0)):
 p=folder/'capture.json'
 if not p.exists():continue
 for s in json.loads(p.read_text()).get('screens',[]):
  if s['name'].endswith('-standard-1440'):images[(s['family'],s['appearance']['theme'])]=folder/(s['name']+'.png')
font=base64.b64encode((root/'resources/app/public/vendor/fonts/IBMPlexSans.woff2').read_bytes()).decode()
screens=[('overview','Genel Bakış'),('cp','CP Tracker'),('orders','Siparişler'),('backlog','Backlog'),('shipping','Nakliye'),('koleksiyon','Koleksiyon'),('quotations','Fiyat Masası'),('priceanalysis','Fiyat ve Üretici Analizi'),('manufacturers','Üreticiler'),('licensecards','Lisans Kartları'),('lfl','LFL'),('opencosting','Ön Maliyet'),('source','Veri Yönetimi'),('automations','Otomasyonlar'),('lcwai','LCW AI'),('cp-checklist-settings','Kontrol Ayarları'),('mail-topic','E-posta Ayarları'),('user-create','Kullanıcı Penceresi'),('rail-collapsed','Dar Menü'),('price-history-approved','Onaylı Fiyatlar'),('cp-rule-invalid','Kural Doğrulama'),('earth-offline','Earth Haritası'),('earth-settings','Earth Ayarları'),('login','Giriş'),('startup-ready','Açılış')]
parts=[f'''<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none';img-src data:;font-src data:;style-src 'unsafe-inline';base-uri 'none'"><title>Buyer Log · Manifest · Arayüz incelemesi</title><style>@font-face{{font-family:Plex;src:url(data:font/woff2;base64,{font}) format('woff2');font-weight:100 900;font-display:swap}}*{{box-sizing:border-box}}body{{margin:0;background:#f5f7f9;color:#16212d;font:1rem/1.6 Plex,sans-serif}}main{{max-width:1500px;margin:auto;padding:clamp(16px,3vw,44px)}}header{{max-width:880px}}h1{{font-size:clamp(2rem,4vw,3.6rem);line-height:1.1;font-weight:600}}h2{{margin-top:40px}}.eyebrow{{letter-spacing:.12em;text-transform:uppercase;font-size:.8rem;color:#374454}}nav{{display:flex;gap:8px;flex-wrap:wrap;margin:24px 0}}nav a{{background:#e9edf1;padding:8px 18px;color:#245578;text-decoration:none}}a:focus-visible,summary:focus-visible{{outline:2px solid #356a96;outline-offset:3px}}details{{margin:10px 0;background:#fff}}summary{{padding:16px 20px;cursor:pointer;font-weight:600}}summary:hover{{background:#eaf2f8}}figure{{margin:0}}img{{display:block;width:100%;height:auto}}figcaption{{padding:12px 20px;font-size:.85rem;color:#374454}}footer{{margin-top:40px;font-size:.9rem;color:#374454}}.note{{padding:16px 20px;background:#e9edf1}}@media(prefers-reduced-motion:reduce){{*{{scroll-behavior:auto}}}}</style></head><body><main><header><p class="eyebrow">Buyer Log / Manifest</p><h1>Ortak bir çalışma dili.</h1><p>Eski tablo başlık renkleri ve açık/koyu temanın nötrleri korundu. Gri tema dengelendi. Ana sütun grupları ince çizgilerle ayrılıyor; kontroller, yazı ve durumlar aynı sistemi kullanıyor.</p><p class="note">Bunlar anonim verilerle gerçek Buyer Log ekran görüntüleridir. Başlıkları açarak inceleyebilirsiniz. Görseller ve font bu HTML dosyasına gömülüdür; çevrimdışı çalışır. Bu belge canlı uygulama değildir.</p><nav aria-label="Temalar"><a href="#light">Açık</a><a href="#grey">Gri</a><a href="#dark">Koyu</a></nav></header>''']
manifest=[]
for theme,label in [('light','Açık'),('grey','Gri'),('dark','Koyu')]:
 parts.append(f'<section id="{theme}"><h2>{label} tema</h2>')
 for family,title in screens:
  if (family,theme) not in images:continue
  p=images[(family,theme)];data=p.read_bytes();manifest.append({'family':family,'theme':theme,'source':str(p.relative_to(root)),'sha256':hashlib.sha256(data).hexdigest()})
  parts.append(f'<details{(" open" if family=="cp" else "")}><summary>{html.escape(title)}</summary><figure><img src="data:image/png;base64,{base64.b64encode(data).decode()}" width="1440" height="900" alt="{html.escape(title)} · {label} tema · Anonim Buyer Log verisi"><figcaption>Gerçek PNG · 1440 × 900 · Standart boyut. Tam doğrulama matrisi ayrıca dört arayüz boyutunu ve 1280 × 720 görünümünü içerir.</figcaption></figure></details>')
 parts.append('</section>')
parts.append('<footer>Yerel inceleme belgesi · PR/CI, merge ve TEST/STABLE durumları kapanış raporunda ayrı belirtilir.<br>Buyer Log 7.0.294 · Manifest</footer></main></body></html>')
target=root/'docs/ai/ui-rebuild/manifest-final.html';target.write_text('\n'.join(parts));Path('/workspace/Buyer-Log-Manifest-Final.html').write_bytes(target.read_bytes());(root/'docs/ai/ui-rebuild/phase-3/gallery-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n');print(len(manifest),'PNGs',target.stat().st_size,'bytes')
